import numpy as np
from scipy.optimize import minimize
vy=np.var(sigma)
sT=np.sqrt(T)
def mk(form,th):
    q,s,d=th[0],th[1],th[2]
    if form=='eps/T': z=eps/T
    elif form=='eps*T': z=eps*T
    elif form=='eps-T': z=eps-T
    if form=='eps-T':
        return np.exp(-s*(eps-T)**2)
    return z**q*np.exp(-s*z)
def gfun(kind,d):
    return np.exp(-d/T) if kind=='exp' else T**d
def obj(th,form,kind):
    f=mk(form,th)
    A=np.column_stack([sT,gfun(kind,th[2]),f])
    c=np.linalg.lstsq(A,sigma,rcond=None)[0]
    return np.mean((sigma-A@c)**2)/vy
